/**
 * Start/stop chimes (port of src/ui/voice/sounds.ts). The WAVs are generated by
 * mobile/scripts/make-chimes.mjs with the web's notes. Silent when sounds are off
 * or the user asked the OS to reduce motion (the web's prefers-reduced-motion).
 */
import { AccessibilityInfo } from "react-native";
import { createAudioPlayer } from "expo-audio";

export type Chime = "start" | "stop";

const SOURCES: Record<Chime, number> = {
  start: require("../../../assets/sounds/start.wav") as number,
  stop: require("../../../assets/sounds/stop.wav") as number,
};

export function playChime(kind: Chime, enabled: boolean): void {
  if (!enabled) return;
  void (async () => {
    if (await AccessibilityInfo.isReduceMotionEnabled().catch(() => false)) return;
    const player = createAudioPlayer(SOURCES[kind]);
    player.play();
    setTimeout(() => { try { player.remove(); } catch { /* already released */ } }, 1_200);
  })().catch(() => undefined);
}
